from pathlib import Path
import ast, json, os, stat
from collections import defaultdict

input_dir = Path('/inputs')
out_path = Path('/work/layout.json')

# Read the requested reference strictly as inert UTF-8 text.
_ = (input_dir / 'smell-catalog.md').read_text(encoding='utf-8')

paths = []
for p in input_dir.iterdir():
    try:
        is_regular = stat.S_ISREG(p.lstat().st_mode)
    except FileNotFoundError:
        continue
    if not is_regular or p.suffix != '.py':
        continue
    if p.name == '__init__.py' or p.name.startswith('test_') or p.name.endswith('_test.py'):
        continue
    paths.append(p)
paths.sort(key=lambda p: p.name)

texts = {p.name: p.read_text(encoding='utf-8') for p in paths}
line_counts = {name: len(text.splitlines()) for name, text in texts.items()}
stem_to_name = {Path(name).stem: name for name in texts}
included_stems = set(stem_to_name)


def sibling_from_components(components):
    if components and components[0] in included_stems:
        return stem_to_name[components[0]]
    return None


def imports_for(name, text):
    tree = ast.parse(text, filename=str(input_dir / name))
    found = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                parts = alias.name.split('.')
                if len(parts) >= 3 and parts[:2] == ['skillc', 'frontend']:
                    target = sibling_from_components(parts[2:])
                    if target is not None and target != name:
                        found.add(target)
        elif isinstance(node, ast.ImportFrom):
            if node.level == 1:
                if node.module:
                    target = sibling_from_components(node.module.split('.'))
                    if target is not None and target != name:
                        found.add(target)
                else:
                    for alias in node.names:
                        if alias.name == '*':
                            continue
                        target = sibling_from_components(alias.name.split('.'))
                        if target is not None and target != name:
                            found.add(target)
            elif node.level == 0 and node.module:
                parts = node.module.split('.')
                if parts == ['skillc', 'frontend']:
                    for alias in node.names:
                        if alias.name == '*':
                            continue
                        target = sibling_from_components(alias.name.split('.'))
                        if target is not None and target != name:
                            found.add(target)
                elif len(parts) >= 3 and parts[:2] == ['skillc', 'frontend']:
                    target = sibling_from_components(parts[2:])
                    if target is not None and target != name:
                        found.add(target)
            # level > 1 is intentionally ignored.
    return sorted(found)

imports = {name: imports_for(name, text) for name, text in texts.items()}
files_rows = [
    {'name': name, 'lines': line_counts[name], 'imports': imports[name]}
    for name in sorted(texts)
]

# Index every qualifying prefix by the complete set of matching stems.
set_to_prefixes = defaultdict(set)
for stem in sorted(included_stems):
    for length in range(4, len(stem) + 1):
        prefix = stem[:length]
        members = frozenset(s for s in included_stems if s.startswith(prefix))
        if len(members) >= 3:
            set_to_prefixes[members].add(prefix)

def longest_common_prefix(strings):
    values = sorted(strings)
    first, last = values[0], values[-1]
    i = 0
    while i < min(len(first), len(last)) and first[i] == last[i]:
        i += 1
    return first[:i]

prefix_rows = []
for member_stems in set_to_prefixes:
    member_names = sorted(stem_to_name[s] for s in member_stems)
    prefix_rows.append({
        'prefix': longest_common_prefix(member_stems),
        'files': member_names,
        'lines': sum(line_counts[n] for n in member_names),
    })
prefix_rows.sort(key=lambda row: row['prefix'])

# Transitive closure from roots with at least three direct sibling imports.
import_tree_rows = []
for root in sorted(imports):
    if len(imports[root]) < 3:
        continue
    reached = set()
    stack = [root]
    while stack:
        current = stack.pop()
        if current in reached:
            continue
        reached.add(current)
        stack.extend(imports[current])
    if len(reached) >= 5:
        member_names = sorted(reached)
        import_tree_rows.append({
            'root': root,
            'files': member_names,
            'lines': sum(line_counts[n] for n in member_names),
        })
import_tree_rows.sort(key=lambda row: row['root'])

result = {
    'files': files_rows,
    'prefix_clusters': prefix_rows,
    'import_tree_clusters': import_tree_rows,
}
out_path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(f'wrote {out_path} ({out_path.stat().st_size} bytes)')
print(json.dumps(result, ensure_ascii=False, indent=2))

from pathlib import Path
import ast, json
p=Path('/work/layout.json')
raw=p.read_text(encoding='utf-8')

def no_dupes(pairs):
    d={}
    for k,v in pairs:
        assert k not in d, f'duplicate key {k}'
        d[k]=v
    return d
obj=json.loads(raw, object_pairs_hook=no_dupes)
assert list(obj)==['files','prefix_clusters','import_tree_clusters']
assert [r['name'] for r in obj['files']] == sorted(r['name'] for r in obj['files'])
assert all(list(r)==['name','lines','imports'] and type(r['lines']) is int and r['imports']==sorted(set(r['imports'])) for r in obj['files'])
assert all(list(r)==['prefix','files','lines'] and type(r['lines']) is int for r in obj['prefix_clusters'])
assert all(list(r)==['root','files','lines'] and type(r['lines']) is int for r in obj['import_tree_clusters'])
assert [r['prefix'] for r in obj['prefix_clusters']] == sorted(r['prefix'] for r in obj['prefix_clusters'])
assert [r['root'] for r in obj['import_tree_clusters']] == sorted(r['root'] for r in obj['import_tree_clusters'])
assert raw.endswith('\n')
print('validated UTF-8 JSON structure, ordering, exact row keys, unique imports, and integer counts')
print('file rows:', len(obj['files']), 'prefix clusters:', len(obj['prefix_clusters']), 'import-tree clusters:', len(obj['import_tree_clusters']))

# Show all statically relevant package-relative/absolute AST imports as a review aid.
for row in obj['files']:
    name=row['name']; text=(Path('/inputs')/name).read_text(encoding='utf-8')
    candidates=[]
    for n in ast.walk(ast.parse(text, filename=name)):
        if isinstance(n, ast.Import):
            vals=[a.name for a in n.names if a.name=='skillc.frontend' or a.name.startswith('skillc.frontend.')]
            if vals: candidates.append((n.lineno, 'import', vals))
        elif isinstance(n, ast.ImportFrom):
            if n.level or n.module=='skillc.frontend' or (n.module or '').startswith('skillc.frontend.'):
                candidates.append((n.lineno, 'from', n.level, n.module, [a.name for a in n.names]))
    if candidates:
        print(name, '=>', row['imports'])
        for c in sorted(candidates): print(' ', c)

